/**
 * Adaptive components — point-placed parametric families.
 *
 * Revit's adaptive components place flexible families on N ordered points
 * (rafters following a curved grid, curtain-wall mullions on a divided
 * path, façade fins between floors). This engine brings the same concept:
 *
 *   - An `AdaptiveFamily` is a cross-section profile plus a point count
 *     (2–4). Instances are placed by supplying that many 3D points.
 *   - Geometry is generated by sweeping the profile along the polyline
 *     through the points, re-orienting the section per segment (upvector
 *     falls back gracefully for vertical segments).
 *   - Pattern helpers divide lines/arcs/paths into bays and slide
 *     multi-point families along a path.
 *   - Output is a watertight indexed mesh; `meshVolume` recovers exact
 *     volumes for quantity takeoff.
 *
 * Pure module: no DOM, no three.js. Safe to unit-test in Node.
 */

/** 3D point. */
export interface Pt3 {
  x: number;
  y: number;
  z: number;
}

/** 2D profile point in the section plane (metres). */
export interface ProfilePt {
  u: number;
  v: number;
}

export interface AdaptiveFamily {
  id: string;
  name: string;
  /** How many placement points an instance needs (2–4). */
  pointCount: number;
  /** Closed cross-section polygon (metres), CCW in the (u, v) plane. */
  profile: ProfilePt[];
}

export interface AdaptiveInstance {
  familyId: string;
  /** Ordered placement points; length must equal the family's pointCount. */
  points: Pt3[];
}

export interface IndexedMesh {
  vertices: Pt3[];
  /** Triangle indices into `vertices`. */
  faces: [number, number, number][];
}

// ── Family registry ─────────────────────────────────────────────────────────

const families = new Map<string, AdaptiveFamily>();

/** Register (or replace) an adaptive family definition. */
export function registerFamily(f: AdaptiveFamily): AdaptiveFamily {
  if (f.pointCount < 2 || f.pointCount > 4) {
    throw new Error(`pointCount must be 2..4, got ${f.pointCount}`);
  }
  if (!f.profile || f.profile.length < 3) {
    throw new Error("profile needs at least 3 points");
  }
  families.set(f.id, f);
  return f;
}

export function getFamily(id: string): AdaptiveFamily | undefined {
  return families.get(id);
}

export function listFamilies(): AdaptiveFamily[] {
  return [...families.values()];
}

/** Instantiate a family at the given ordered points and generate its mesh. */
export function instantiate(familyId: string, points: Pt3[]): IndexedMesh {
  const fam = families.get(familyId);
  if (!fam) throw new Error(`unknown adaptive family ${familyId}`);
  if (points.length !== fam.pointCount) {
    throw new Error(`family ${familyId} needs ${fam.pointCount} points, got ${points.length}`);
  }
  return sweepProfile(fam.profile, points);
}

// ── Sweeping ────────────────────────────────────────────────────────────────

/**
 * Sweep a closed 2D profile along the polyline through `path` points.
 * Returns a closed indexed mesh (both caps included).
 */
export function sweepProfile(profile: ProfilePt[], path: Pt3[]): IndexedMesh {
  if (path.length < 2) throw new Error("sweep needs at least 2 path points");
  const vertices: Pt3[] = [];
  const faces: [number, number, number][] = [];
  const n = profile.length;

  for (let s = 0; s < path.length - 1; s++) {
    const a = path[s];
    const b = path[s + 1];
    const T = norm3(sub3(b, a));
    if (len3(T) < 1e-12) throw new Error("zero-length segment in adaptive path");
    // Section frame: N ⊥ T in the "most vertical" plane.
    const ref: Pt3 = Math.abs(T.z) < 0.99 ? { x: 0, y: 0, z: 1 } : { x: 1, y: 0, z: 0 };
    const N = norm3(cross3(ref, T));
    const B = cross3(T, N);

    const base = vertices.length;
    for (const p of path.slice(s, s + 2)) {
      for (const c of profile) {
        vertices.push({
          x: p.x + N.x * c.u + B.x * c.v,
          y: p.y + N.y * c.u + B.y * c.v,
          z: p.z + N.z * c.u + B.z * c.v,
        });
      }
    }
    const s1 = base;             // start ring
    const s2 = base + n;         // end ring

    // Caps (start cap wound so its normal points backwards along T).
    for (let i = 1; i < n - 1; i++) {
      faces.push([s1, s1 + i + 1, s1 + i]); // reversed: normal −T
      faces.push([s2, s2 + i, s2 + i + 1]);
    }
    // Side quads.
    for (let i = 0; i < n; i++) {
      const j = (i + 1) % n;
      faces.push([s1 + i, s1 + j, s2 + j]);
      faces.push([s1 + i, s2 + j, s2 + i]);
    }
  }
  return { vertices, faces };
}

/**
 * Signed volume of a closed triangle mesh (divergence theorem). Positive
 * when face winding is outward. Used for quantity takeoff of adaptive
 * instances.
 */
export function meshVolume(mesh: IndexedMesh): number {
  let v = 0;
  for (const [ia, ib, ic] of mesh.faces) {
    const a = mesh.vertices[ia];
    const b = mesh.vertices[ib];
    const c = mesh.vertices[ic];
    v += dot3(a, cross3(b, c)) / 6;
  }
  return v;
}

/** Shoelace area of the closed 2D profile (positive for CCW). */
export function profileArea(profile: ProfilePt[]): number {
  let a = 0;
  for (let i = 0; i < profile.length; i++) {
    const p = profile[i];
    const q = profile[(i + 1) % profile.length];
    a += p.u * q.v - q.u * p.v;
  }
  return a / 2;
}

// ── Path / pattern helpers ──────────────────────────────────────────────────

/** Divide the segment a→b into `bays` equal bays; returns bays+1 points. */
export function divideLine(a: Pt3, b: Pt3, bays: number): Pt3[] {
  if (bays < 1) throw new Error("bays must be >= 1");
  const out: Pt3[] = [];
  for (let i = 0; i <= bays; i++) {
    const t = i / bays;
    out.push({ x: a.x + (b.x - a.x) * t, y: a.y + (b.y - a.y) * t, z: a.z + (b.z - a.z) * t });
  }
  return out;
}

/** Divide a circular arc (CCW from startAngle to endAngle) into bays. */
export function divideArc(
  center: Pt3, radius: number, startAngle: number, endAngle: number, bays: number,
): Pt3[] {
  if (bays < 1) throw new Error("bays must be >= 1");
  const out: Pt3[] = [];
  for (let i = 0; i <= bays; i++) {
    const ang = startAngle + ((endAngle - startAngle) * i) / bays;
    out.push({ x: center.x + radius * Math.cos(ang), y: center.y + radius * Math.sin(ang), z: center.z });
  }
  return out;
}

/**
 * Slide a family along a divided path: a window of `pointCount` points
 * steps one bay at a time, producing path.length − pointCount + 1
 * instances (the Revit "Repeater" behaviour for point arrays).
 */
export function repeatAlongPath(familyId: string, path: Pt3[]): AdaptiveInstance[] {
  const fam = families.get(familyId);
  if (!fam) throw new Error(`unknown adaptive family ${familyId}`);
  const w = fam.pointCount;
  if (path.length < w) return [];
  const out: AdaptiveInstance[] = [];
  for (let i = 0; i + w <= path.length; i++) {
    out.push({ familyId, points: path.slice(i, i + w) });
  }
  return out;
}

/** Total polyline length through the points (m). */
export function pathLength(points: Pt3[]): number {
  let L = 0;
  for (let i = 1; i < points.length; i++) L += len3(sub3(points[i], points[i - 1]));
  return L;
}

// ── Vector helpers ──────────────────────────────────────────────────────────

function sub3(a: Pt3, b: Pt3): Pt3 {
  return { x: a.x - b.x, y: a.y - b.y, z: a.z - b.z };
}
function cross3(a: Pt3, b: Pt3): Pt3 {
  return { x: a.y * b.z - a.z * b.y, y: a.z * b.x - a.x * b.z, z: a.x * b.y - a.y * b.x };
}
function dot3(a: Pt3, b: Pt3): number {
  return a.x * b.x + a.y * b.y + a.z * b.z;
}
function len3(a: Pt3): number {
  return Math.hypot(a.x, a.y, a.z);
}
function norm3(a: Pt3): Pt3 {
  const l = len3(a);
  if (l < 1e-12) throw new Error("cannot normalise zero vector");
  return { x: a.x / l, y: a.y / l, z: a.z / l };
}
